public int LengthOfLongestSubstring(string s) {
    var window = new HashSet<char>();
    int l = 0, best = 0;
    for (int r = 0; r < s.Length; r++) {
        while (window.Contains(s[r])) window.Remove(s[l++]);   // shrink while the duplicate is inside
        window.Add(s[r]);
        best = Math.Max(best, r - l + 1);                       // repeat-free again
    }
    return best;
}

