public int LengthOfLongestSubstring(string s) {
    var next = new int[128];          // next[c] = index of the last c + 1; 0 means not seen
    int l = 0, best = 0;
    for (int r = 0; r < s.Length; r++) {
        char c = s[r];
        l = Math.Max(l, next[c]);     // jump past the previous c, but never backwards
        next[c] = r + 1;
        best = Math.Max(best, r - l + 1);
    }
    return best;
}

